			ctx, model.AuditLogEventNewClientAuthorization,
			ipAddress, userAgent, userID,
			model.AuditLogData{"clientName": client.Name},
			tx,
		)
	}

	err = tx.Commit().Error
	if err != nil {
		return "", "", fmt.Errorf("failed to commit transaction: %w", err)
	}

	return code, callbackURL, nil
}

