			}
			name := pathname[6:]
			js, ok := getNodeRuntimeJS(name)
			if !ok {
				if !nodeBuiltinModules[name] {
					ctx.SetHeader("Cache-Control", ccImmutable)
					return rex.Status(404, "Not Found")
				}
