					}
				}

				warning.Results = append(warning.Results, s)
			}
		}

	}

	total := y + n + p
	warning.Score.Supported = y / total * 100
	warning.Score.Unsupported = n / total * 100
	warning.Score.Partial = p / total * 100

	return warning, nil
}

