					}
				}

				l.WithFields(logrus.Fields{
					"build":    rB.GetNumber(),
					"build_id": rB.GetID(),
					"org":      repo.GetOrg(),
					"repo":     repo.GetName(),
					"repo_id":  repo.GetID(),
