					util.HandleError(c, http.StatusInternalServerError, err)
				} else {
					c.JSON(http.StatusCreated, b)
				}

				return
			}

			l.Debugf("fork PR build %s/%d automatically running without approval", repo.GetFullName(), b.GetNumber())
