func (h *handler) showFeedIcon(w http.ResponseWriter, r *http.Request) {
	externalIconID := request.RouteStringParam(r, "externalIconID")
	icon, err := h.store.IconByExternalID(externalIconID)
	if err != nil {
		html.ServerError(w, r, err)
		return
	}

	if icon == nil {
		html.NotFound(w, r)
		return
	}

