					dlErr := fmt.Errorf("download file from to '%s': got status: '%s'", dl.Url, resp.Status)
					dlSpan.RecordError(dlErr)
					dlSpan.SetStatus(codes.Error, dlErr.Error())
					dlSpan.End()
