			})
		}

		err = eg.Wait()
		if err != nil {
			return ctx, cancel, err
		}
	}

	copyToDisk := func(fh *multipart.FileHeader) error {
		in, err := fh.Open()
		if err != nil {
			return fmt.Errorf("open multipart file: %w", err)
		}

		defer func() {
			err := in.Close()
			if err != nil {
				logger.ErrorContext(context.Background(), fmt.Sprintf("close file header: %s", err))
			}
