		path := fmt.Sprintf("%s/%s", ctx.dirPath, safeName)

		out, err := os.Create(path)
		if err != nil {
			return fmt.Errorf("create local file: %w", err)
		}
		defer func() {
			err := out.Close()
			if err != nil {
				logger.ErrorContext(context.Background(), fmt.Sprintf("close local file: %s", err))
			}
		}()

