						log.Info().
							Str("schedule", cfg.TieredStorage.MigrationSchedule).
							Bool("cold_enabled", cfg.TieredStorage.Cold.Enabled).
							Int("default_hot_days", cfg.TieredStorage.DefaultHotMaxAgeDays).
							Msg("Tiered storage enabled")
					}
