func httpErrorSummary(err error) string {
	var re = regexp.MustCompile(`.*: (.*)$`)

	e := err.Error()
	if !re.MatchString(e) {
		return e
	}

	parts := re.FindAllStringSubmatch(e, -1)

	return parts[0][len(parts[0])-1]
}

