	refresh, err := s.storage.GetRefresh(token.RefreshId)
	if err != nil {
		if err != storage.ErrNotFound {
			s.logger.Errorf("failed to get refresh token: %v", err)
			return nil, newInternalServerError()
		}
		return nil, invalidErr
