		ReleaseData: releaseData,
	}

	if err := b.SBOMGenerator.GenerateSBOM(ctx, genCtx); err != nil {
		return fmt.Errorf("generating SBOMs: %w", err)
	}

	// emit main package
	if err := b.Emit(ctx, pkg); err != nil {
		return fmt.Errorf("unable to emit package: %w", err)
	}

